import type { Metadata } from "next";

export const SITE_NAME = "NAV Dental Clinic";

/**
 * The image generated by app/opengraph-image.tsx. Referenced explicitly because
 * Next.js merges metadata shallowly: a page-level `openGraph` object would
 * otherwise drop the file-based image.
 */
const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "NAV Dental Clinic, Somna Road, Pahasu — Dr. Ratan Raghav" };

type PageMeta = {
  title: string;
  description: string;
  /** Canonical path, e.g. "/services/dental-consultation" (resolved against metadataBase). */
  path: string;
  /** Use the title as-is instead of applying the site title template. */
  absoluteTitle?: boolean;
  noindex?: boolean;
};

/**
 * Consistent per-page metadata: unique title and description, canonical URL,
 * Open Graph and Twitter cards with the shared brand image.
 */
export function pageMetadata({ title, description, path, absoluteTitle, noindex }: PageMeta): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}, Pahasu`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: { title: fullTitle, description, url: path, siteName: SITE_NAME, locale: "en_IN", type: "website", images: [SHARE_IMAGE] },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [SHARE_IMAGE.url] },
    ...(noindex ? { robots: { index: false, follow: true } } : {}),
  };
}
